#include <stdint.h>
#include <stdio.h>

int main(void) {
    uint32_t valor = 0x12345678;
    unsigned char *bytes = (unsigned char *)&valor;
    for (size_t i = 0; i < sizeof(valor); i++)
        printf("%02X%s", (unsigned int)bytes[i], i + 1 == sizeof(valor) ? "\n" : " ");
    return 0;
}
